"""Capture observed development-player attack frames from the real game canvas."""
import argparse,base64,json
from pathlib import Path
from PIL import Image
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--url',default='http://127.0.0.1:8011');p.add_argument('--output',type=Path,default=Path(__file__).resolve().parent);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True);errors=[]
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);page=browser.new_page(viewport={'width':1280,'height':800});page.set_default_timeout(120000);page.on('pageerror',lambda e:errors.append(str(e)));url=a.url.rstrip('/')+'/index.html?qa=1&swordsman=v3-painted-v2';page.goto(url,wait_until='networkidle');page.locator('#newname').fill('Swordsman Development');page.locator('#create').click();page.wait_for_selector('#world');page.wait_for_function('window.AstraeonQA && AstraeonQA.snapshot().sockets.spriteSockets');fixture=page.evaluate('''()=>{const save=AstraeonQA.snapshot().save,w=AstraeonContent.nativeWorld;return {...save,x:w.safeSpawn[0],y:w.safeSpawn[1],worldLayout:w.layoutId}}''');page.goto(a.url.rstrip('/')+'/icon.svg');page.evaluate('save=>localStorage.setItem("astraeon-iso-v1",JSON.stringify(save))',fixture);page.goto(url,wait_until='networkidle');page.wait_for_selector('#world');page.wait_for_function('window.AstraeonQA && AstraeonQA.snapshot().sockets.spriteSockets');page.keyboard.down('d');page.wait_for_function('AstraeonSwordsmanDevelopment.snapshot().currentClip==="Walk"');page.wait_for_timeout(900);page.keyboard.up('d');page.wait_for_function('AstraeonSwordsmanDevelopment.snapshot().currentClip==="Idle"');page.evaluate('async()=>AstraeonSwordsmanDevelopment.prepare("BasicAttack")')
 page.evaluate('''()=>{window.attackEvidence=new Promise((resolve,reject)=>{let frames=[],started=false,lastKey=null;const deadline=performance.now()+30000;function step(){const s=AstraeonQA.snapshot(),actor=s.renderer.actors.find(a=>a.id==='player'),dev=AstraeonSwordsmanDevelopment.snapshot();if(s.animation.state==='attack'&&dev.currentClip==='BasicAttack'&&actor?.motionSample?.frame){started=true;const f=actor.motionSample.frame,key=f.row+':'+f.column;if(key!==lastKey){const v=AstraeonSpatialView,w=document.getElementById('world');const c=document.createElement('canvas');c.width=480;c.height=480;const x=c.getContext('2d');x.drawImage(v.canvas,400,100,480,480,0,0,480,480);x.drawImage(w,400,100,480,480,0,0,480,480);frames.push({frame:f,time:s.time,image:c.toDataURL('image/png')});lastKey=key;}}else if(started){resolve(frames);return}if(performance.now()>deadline){reject(Error('Attack evidence timed out'));return}requestAnimationFrame(step)}requestAnimationFrame(step)})}''');page.keyboard.press('f');frames=page.evaluate('()=>window.attackEvidence');browser.close()
assert not errors,errors
images=[];metadata=[]
for i,f in enumerate(frames):
 path=a.output/f'frame-{i:02d}.png';path.write_bytes(base64.b64decode(f.pop('image').split(',')[1]));im=Image.open(path).convert('RGB');images.append(im);metadata.append({'index':i,**f})
assert images,'No attack frames observed'
durations=[max(10,round((metadata[i+1]['time']-metadata[i]['time'])*100)*10) for i in range(len(images)-1)]+[100];images[0].save(a.output/'attack-game.gif',save_all=True,append_images=images[1:],duration=durations,disposal=2,optimize=False)
(a.output/'capture.json').write_text(json.dumps({'status':'DEVELOPMENT_GAME_CAPTURE_NOT_VISUAL_APPROVAL','frames':metadata,'gif_durations_ms':durations,'capture_method':'unique animation row/column observed at requestAnimationFrame; game canvas plus spatial canvas','missing_source_frames_may_be_skipped':True,'gif_crop_canvas_pixels':[400,100,880,580],'gif_plays_once':True,'page_errors':errors,'runtime_admitted':False},indent=2)+'\n');print(json.dumps({'captured_frames':len(images),'columns':[x['frame']['column'] for x in metadata],'durations_ms':durations}))
